-- Horários reais das agendas manuscritas, corrigindo os valores do 001_seed.
-- As condições no where fazem o ajuste valer só enquanto o cadastro estiver no
-- default semeado: se alguém mudar o horário pelo sistema, um restart não desfaz.
update professionals
set "workingHoursEnd" = '19:00',
    notes = 'Sócia-fundadora do consultório. Atende de 8h às 12h e de 14h às 18h30, em intervalos de 30 minutos.'
where id = 'prof-1'
  and "workingHoursStart" = '08:00' and "workingHoursEnd" = '18:00' and "defaultDuration" = 30;

update professionals
set "workingHoursStart" = '08:00',
    "workingHoursEnd" = '18:00',
    "defaultDuration" = 30,
    notes = 'Sócia-fundadora do consultório. Atende de 8h às 12h e de 14h30 às 18h, em intervalos de 30 minutos.'
where id = 'prof-2'
  and "workingHoursStart" = '09:00' and "workingHoursEnd" = '17:00' and "defaultDuration" = 45;

-- A paciente de demonstração "Maria das Dores Silva" (pat-1) e o contato ctc-1
-- vêm do 001_seed, que é anterior a este arquivo e roda a cada boot. Como o
-- consultório agora usa dados reais, ela é removida aqui em seguida.
-- Contatos primeiro: contacts."patientId" referencia patients(id).
delete from contacts where id = 'ctc-1' or "patientId" = 'pat-1';
delete from appointments_cache where "patientId" = 'pat-1';
delete from patients where id = 'pat-1';
